-- change ecpay-per-shop-credentials: each shop's own payment provider
-- credentials (design D5), replacing the platform-wide ECPAY_* env vars.
--
-- Hand-written rather than generated by cmd/migrategen (no dev database
-- available in this environment to run the atlas diff against) — the shape
-- below is transcribed directly from the ent-generated
-- internal/ent/migrate/schema.go (ShopPaymentProviderCredentialsTable),
-- which is itself derived from internal/ent/schema/paymentcredential.go, so
-- there is no independent judgment call in the column list, types, FK name,
-- or index name below; a real `make migrate-gen` run would be expected to
-- reproduce this file byte-for-byte modulo comments. Same caveat as every
-- sibling migration: no handwritten constraint here needs preserving (this
-- is a brand new table, nothing to drop).
--
-- hash_key_ciphertext/hash_iv_ciphertext are `bytea`: cryptbox.Box.Encrypt
-- output (nonce||ciphertext), never plaintext (design D3/D4).
--
-- No backfill: an empty table means "no shop has configured ecpay
-- credentials yet", which is exactly true.

-- ── shop_payment_provider_credentials ──────────────────────────────────
CREATE TABLE "shop_payment_provider_credentials" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "created_at" timestamptz NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "provider" character varying(32) NOT NULL,
    "merchant_id" character varying(191) NOT NULL,
    "hash_key_ciphertext" bytea NOT NULL,
    "hash_iv_ciphertext" bytea NOT NULL,
    "choose_payment" character varying(32) NULL,
    "shop_id" bigint NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "shop_payment_provider_credentials_shops_shop" FOREIGN KEY ("shop_id") REFERENCES "shops" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- One credential set per provider per shop (design D5).
CREATE UNIQUE INDEX "shoppaymentprovidercredential_shop_id_provider" ON "shop_payment_provider_credentials" ("shop_id", "provider");
